78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
82	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
86	
87	    /**
88	     * Domains that supply disposable / throwaway mailboxes. An owner whose email domain matches one of
89	     * these (compared case-insensitively) is rejected. Values are stored lower-cased for comparison.
90	     */
91	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
92	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
93	
94	    /**
95	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
96	     * line here so audit trails can be captured independently of application logging.
97	     */
98	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
99	
100	    private final ClinicService clinicService;
101	
102	    private final OwnerMapper ownerMapper;
103	
104	    private final PetMapper petMapper;
105	
106	    private final VisitMapper visitMapper;
107	
108	    public OwnerRestControllerV1(ClinicService clinicService,
109	                                 OwnerMapper ownerMapper,
110	                                 PetMapper petMapper,
111	                                 VisitMapper visitMapper) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        rejectMissingOrBlankFields(ownerFieldsDto);
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        applyAddress(owner);
150	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
151	        owner.setEmail(normalizeEmail(owner.getEmail()));
152	        validatePostcode(owner.getPostcode(), owner.getCity());
153	        rejectFutureRegistrationDate(owner.getRegistrationDate());
154	        if (owner.getRegistrationDate() == null) {
155	            owner.setRegistrationDate(LocalDate.now());
156	        }
157	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
158	        rejectDailyLimitReached(owner.getRegistrationDate());
159	        rejectCityAtCapacity(owner.getCity());
160	        owner.setHouseholdId(computeHouseholdId(owner));
161	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
162	        rejectDuplicateIdentity(owner);
163	        if (!sharesHousehold) {
164	            rejectHouseholdDuplicate(owner);
165	        }
166	        assignPossibleDuplicate(owner, sharesHousehold);
167	        owner.setCustomerCode(generateCustomerCode(owner));
168	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
169	        owner.setHouseholdSize(countHouseholdSize(owner.getHouseholdId()));
170	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
174	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
175	            ownerDto.getMembershipNumber());
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
