247	    @Override
248	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
249	        HttpHeaders headers = new HttpHeaders();
250	        Visit visit = visitMapper.toVisit(visitFieldsDto);
251	        Pet pet = new Pet();
252	        pet.setId(petId);
253	        visit.setPet(pet);
254	        this.clinicService.saveVisit(visit);
255	        VisitDto visitDto = visitMapper.toVisitDto(visit);
256	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
257	            .buildAndExpand(visit.getId()).toUri());
258	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
259	    }
260	
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
265	        Owner owner = this.clinicService.findOwnerById(ownerId);
266	        if (owner != null) {
267	            Pet pet = owner.getPet(petId);
268	            if (pet != null) {
269	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
270	            }
271	        }
272	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	    }
274	
275	    /**
276	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
277	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
278	     *
279	     * @param fields the submitted owner fields
280	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
281	     *                                        {@code null} or blank, or if the owner supplies no address
282	     *                                        in either form (a blank structured {@code addressLine1} and a
283	     *                                        blank flat {@code address}, each measured after normalization)
284	     */
285	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
286	        List<String> missing = new ArrayList<>();
287	        if (isBlank(fields.getFirstName())) {
288	            missing.add("firstName");
289	        }
290	        if (isBlank(fields.getLastName())) {
291	            missing.add("lastName");
292	        }
293	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
294	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
295	        if (!hasStructuredAddress && !hasFlatAddress) {
296	            missing.add("address");
297	        }
298	        if (isBlank(fields.getCity())) {
299	            missing.add("city");
300	        }
301	        if (isBlank(fields.getTelephone())) {
302	            missing.add("telephone");
303	        }
304	        if (!missing.isEmpty()) {
305	            throw new RequiredFieldsMissingException(missing);
306	        }
307	    }
308	
309	    private boolean isBlank(String value) {
310	        return value == null || value.isBlank();
311	    }
312	
313	    /**
314	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
315	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
316	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
317	     */
318	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
319	        "NSW", new int[] {2000, 2099},
320	        "VIC", new int[] {3000, 3099},
321	        "QLD", new int[] {4000, 4099});
322	
323	    /**
324	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
325	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
326	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
327	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
328	     *
329	     * @param postcode the submitted postcode, or {@code null} when omitted
330	     * @param city the owner's city, used to derive the region whose range constrains the postcode
331	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
332	     *                                  city's region
333	     */
334	    private void validatePostcode(String postcode, String city) {
335	        if (postcode == null) {
336	            return;
337	        }
338	        if (!postcode.matches("[0-9]{4}")) {
339	            throw new InvalidPostcodeException(postcode);
340	        }
341	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
342	        if (range == null) {
343	            return;
344	        }
345	        int value = Integer.parseInt(postcode);
346	        if (value < range[0] || value > range[1]) {
347	            throw new InvalidPostcodeException(postcode);
348	        }
349	    }
350	
351	    /**
352	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
353	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
354	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
355	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
356	     * <p>
357	     * Where a per-country rule is defined the national-number length is validated against the country
358	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
359	     * requires exactly 10.
360	     *
361	     * @param telephone the raw telephone value from the request
362	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
363	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
364	     */
365	    private String normalizeTelephone(String telephone) {
366	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
367	        String digits;
368	        if (cleaned.startsWith("+")) {
369	            digits = cleaned.substring(1);
370	        } else {
371	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
372	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
373	            digits = "61" + national;
374	        }
375	        if (!digits.matches("[0-9]{8,15}")) {
376	            throw new InvalidTelephoneException(cleaned);
377	        }
378	        // Validate the national-number length against the country code where a rule is defined.
379	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
380	            throw new InvalidTelephoneException(cleaned);
381	        }
382	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
383	            throw new InvalidTelephoneException(cleaned);
384	        }
385	        return "+" + digits;
386	    }
387	
388	    /**
389	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
390	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
391	     * lower-cased.
392	     *
393	     * @param email the raw email value from the request, or {@code null} if omitted
394	     * @return the lower-cased email, or {@code null} if none was supplied
395	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
396	     */
397	    private String normalizeEmail(String email) {
398	        if (email == null) {
399	            return null;
400	        }
401	        String trimmed = email.strip();
402	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
403	            throw new InvalidEmailException(email);
404	        }
405	        String normalized = trimmed.toLowerCase(Locale.ROOT);
406	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
407	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
408	            throw new DisposableEmailDomainException(domain);
409	        }
410	        return normalized;
411	    }
412	
413	    /**
414	     * Applies the owner's address in whichever form the request supplied, preferring the structured
415	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
416	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
417	     * value: the normalized {@code addressLine1}, with a single space and the normalized
418	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
419	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
420	     * flat-address contract backward-compatible.
421	     *
422	     * @param owner the owner being created, mapped straight from the request
423	     */
424	    private void applyAddress(Owner owner) {
425	        if (!isBlank(owner.getAddressLine1())) {
426	            String line1 = normalizeAddress(owner.getAddressLine1());
427	            owner.setAddressLine1(line1);
428	            String composed = line1;
429	            if (!isBlank(owner.getAddressLine2())) {
430	                String line2 = normalizeAddress(owner.getAddressLine2());
431	                owner.setAddressLine2(line2);
432	                composed = line1 + " " + line2;
433	            } else {
434	                owner.setAddressLine2(null);
435	            }
436	            owner.setAddress(composed);
437	        } else {
438	            owner.setAddressLine1(null);
439	            owner.setAddressLine2(null);
440	            owner.setAddress(normalizeAddress(owner.getAddress()));
441	        }
442	    }
443	
444	    /**
445	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
446	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
447	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
448	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
449	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
450	     *
451	     * @param address the raw address value from the request (may be {@code null})
452	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
453	     */
454	    private String normalizeAddress(String address) {
455	        if (address == null) {
456	            return "";
457	        }
458	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
459	        if (collapsed.isEmpty()) {
460	            return "";
461	        }
462	        String[] tokens = collapsed.split(" ");
463	        StringBuilder sb = new StringBuilder(collapsed.length());
464	        for (int i = 0; i < tokens.length; i++) {
465	            if (i > 0) {
466	                sb.append(' ');
467	            }
468	            sb.append(expandAddressAbbreviation(tokens[i]));
469	        }
470	        return sb.toString();
471	    }
472	
473	    /**
474	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
475	     * returns the token unchanged when it is not a recognised abbreviation.
476	     *
477	     * @param token an upper-cased whole-word address token
478	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
479	     */
480	    private String expandAddressAbbreviation(String token) {
481	        return switch (token) {
482	            case "ST" -> "STREET";
483	            case "RD" -> "ROAD";
484	            case "AVE" -> "AVENUE";
485	            default -> token;
486	        };
487	    }
488	
489	    /**
490	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
491	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
492	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
493	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
494	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}).
495	     * <p>
496	     * Should the computed code collide with an existing owner's {@code customerCode}, it is de-duplicated
497	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
498	     * held by any existing owner; the de-duplicated code is returned.
499	     *
500	     * @param owner the owner being created, with normalized telephone and postcode already set
501	     * @return the assigned, collision-free customer code
502	     */
503	    private String generateCustomerCode(Owner owner) {
504	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
505	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
506	            .substring(0, 8).toUpperCase(Locale.ROOT);
507	        String base = region + "-" + hash8;
508	        Set<String> existing = this.clinicService.findAllOwners().stream()
509	            .map(Owner::getCustomerCode)
510	            .filter(code -> code != null)
511	            .collect(java.util.stream.Collectors.toSet());
512	        if (!existing.contains(base)) {
513	            return base;
514	        }
515	        int n = 2;
516	        while (existing.contains(base + "-" + n)) {
517	            n++;
518	        }
519	        return base + "-" + n;
520	    }
521	
522	    /**
523	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
524	     *
525	     * @param value the value to hash
526	     * @return the 64-character lower-case hex SHA-256 digest
527	     */
528	    private String sha256Hex(String value) {
529	        try {
530	            byte[] digest = MessageDigest.getInstance("SHA-256")
531	                .digest(value.getBytes(StandardCharsets.UTF_8));
532	            StringBuilder sb = new StringBuilder(digest.length * 2);
533	            for (byte b : digest) {
534	                sb.append(String.format("%02x", b));
535	            }
536	            return sb.toString();
537	        } catch (NoSuchAlgorithmException e) {
538	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
539	        }
540	    }
541	
542	    /**
543	     * Counts how many existing owners already share the given first name and last name, compared
544	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
545	     * owner being created.
546	     *
547	     * @param firstName the first name of the owner being created
548	     * @param lastName the last name of the owner being created
549	     * @return the number of existing owners with the same first and last name (case-insensitively)
550	     */
551	    private int countNamesakes(String firstName, String lastName) {
552	        return (int) this.clinicService.findAllOwners().stream()
553	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
554	                && lastName.equalsIgnoreCase(existing.getLastName()))
555	            .count();
556	    }
557	
558	    /**
559	     * Computes the size of the owner's household: the number of existing owners already sharing the given
560	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
561	     * owner is persisted, so adding one for the owner yields the household's total membership including it
562	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
563	     * the deterministic {@code householdId} (derived from last name and postcode).
564	     *
565	     * @param householdId the computed household identifier of the owner being created
566	     * @return the household size including the owner being created (at least 1)
567	     */
568	    private int countHouseholdSize(String householdId) {
569	        long existing = this.clinicService.findAllOwners().stream()
570	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
571	            .count();
572	        return (int) existing + 1;
573	    }
574	
575	    /**
576	     * The maximum number of owners permitted in a single city. A create request whose city already
577	     * holds this many owners is rejected.
578	     */
579	    private static final int CITY_OWNER_LIMIT = 50;
580	
581	    /**
582	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
583	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
584	     * differing only in the casing of their city share one capacity pool. The count is taken before the
585	     * new owner is persisted, so it excludes the owner being created.
586	     *
587	     * @param city the city of the owner being created
588	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
589	     */
590	    private void rejectCityAtCapacity(String city) {
591	        long existing = this.clinicService.findAllOwners().stream()
592	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
593	            .count();
594	        if (existing >= CITY_OWNER_LIMIT) {
595	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
596	        }
597	    }
598	
599	    /**
600	     * The maximum number of owners permitted to be created in a single day. A create request whose
601	     * registration date already holds this many owners is rejected.
602	     */
603	    private static final int DAILY_OWNER_LIMIT = 100;
604	
605	    /**
606	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
607	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
608	     * persisted, so it excludes the owner being created.
609	     *
610	     * @param registrationDate the registration date of the owner being created
611	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
612	     */
613	    /**
614	     * Adjusts an effective registration date so that it always falls on a business day. When the given
615	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
616	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
617	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
618	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
619	     * business-day-adjusted date.
620	     *
621	     * @param date the effective registration date, supplied or defaulted
622	     * @return the same date when it is a weekday, otherwise the next Monday
623	     */
624	    private LocalDate rollToBusinessDay(LocalDate date) {
625	        DayOfWeek day = date.getDayOfWeek();
626	        if (day == DayOfWeek.SATURDAY) {
627	            return date.plusDays(2);
628	        }
629	        if (day == DayOfWeek.SUNDAY) {
630	            return date.plusDays(1);
631	        }
632	        return date;
633	    }
634	
635	    /**
636	     * The number of owners that must already exist for a given day before a further create is flagged as a
637	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
638	     * the created owner carries {@code bulkSignupWarning = true}.
639	     */
640	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
641	
642	    /**
643	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
644	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
645	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
646	     * the daily create-limit rule's accumulation path.
647	     *
648	     * @param registrationDate the registration date of the owner being created
649	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
650	     */
651	    private boolean isBulkSignupDay(LocalDate registrationDate) {
652	        long existing = this.clinicService.findAllOwners().stream()
653	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
654	            .count();
655	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
656	    }
657	
658	    /**
659	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
660	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
661	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
662	     * made against the supplied value before any business-day adjustment.
663	     *
664	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
665	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
666	     */
667	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
668	        if (registrationDate == null) {
669	            return;
670	        }
671	        LocalDate today = LocalDate.now();
672	        if (registrationDate.isAfter(today)) {
673	            throw new FutureRegistrationDateException(registrationDate, today);
674	        }
675	    }
676	
677	    private void rejectDailyLimitReached(LocalDate registrationDate) {
678	        long existing = this.clinicService.findAllOwners().stream()
679	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
680	            .count();
681	        if (existing >= DAILY_OWNER_LIMIT) {
682	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
683	        }
684	    }
685	
686	    /**
687	     * Rejects a create request whose owner collides with an existing owner on the single derived
688	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
689	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
690	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
691	     * household (same {@code householdId}) with different telephones have different keys and are both
692	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
693	     * been computed (deterministically from the last name and postcode) before this check runs, so the
694	     * key compared here is the same one that is later returned.
695	     *
696	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
697	     * @throws DuplicateIdentityException if an existing owner has the same identity key
698	     */
699	    private void rejectDuplicateIdentity(Owner owner) {
700	        String key = identityKey(owner);
701	        boolean taken = this.clinicService.findAllOwners().stream()
702	            .anyMatch(existing -> key.equals(identityKey(existing)));
703	        if (taken) {
704	            throw new DuplicateIdentityException(key);
705	        }
706	    }
707	
708	    /**
709	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
710	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
711	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
712	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
713	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
714	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
715	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
716	     * <p>
717	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
718	     * postcode is now exactly the household key, so such an owner is a known household member rather than
719	     * a suspected duplicate.
720	     *
721	     * @param owner the owner being created, with normalized telephone and validated postcode already set
722	     * @param sharesHousehold whether the create declared the owner a household member
723	     */
724	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
725	        Integer matchId = null;
726	        if (!sharesHousehold && owner.getPostcode() != null) {
727	            matchId = this.clinicService.findAllOwners().stream()
728	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
729	                    && owner.getPostcode().equals(existing.getPostcode())
730	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
731	                .map(Owner::getId)
732	                .filter(id -> id != null)
733	                .min(Comparator.naturalOrder())
734	                .orElse(null);
735	        }
736	        owner.setPossibleDuplicate(matchId != null);
737	        owner.setPossibleDuplicateOf(matchId);
738	    }
739	
740	    private boolean telephonesEqual(String a, String b) {
741	        return a == null ? b == null : a.equals(b);
742	    }
743	
744	    /**
745	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
746	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
747	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
748	     * Telephone and email are stored already normalized, so the stored values are used directly.
749	     *
750	     * @param owner the owner whose identity key is being derived
751	     * @return the owner's identity key
752	     */
753	    private String identityKey(Owner owner) {
754	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
755	        String email = owner.getEmail() == null ? "" : owner.getEmail();
756	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
757	        return telephone + "|" + email + "|" + householdId;
758	    }
759	
760	    /**
761	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
762	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
763	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
764	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
765	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
766	     * whether or not {@code sharesHousehold} was requested.
767	     *
768	     * @param owner the owner being created, with its validated postcode already set
769	     * @return the deterministic household identifier
770	     */
771	    private String computeHouseholdId(Owner owner) {
772	        String normalizedLastName = normalizeForComparison(owner.getLastName());
773	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
774	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
775	    }
776	
777	    /**
778	     * Rejects a create request whose owner would join an existing household without declaring it. The
779	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
780	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
781	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
782	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
783	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
784	     *
785	     * @param owner the owner being created, with its computed {@code householdId} already assigned
786	     * @throws HouseholdDuplicateException if an existing owner already shares the household
787	     */
788	    private void rejectHouseholdDuplicate(Owner owner) {
789	        String householdId = owner.getHouseholdId();
790	        boolean shared = this.clinicService.findAllOwners().stream()
791	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
792	        if (shared) {
793	            throw new HouseholdDuplicateException(householdId);
794	        }
795	    }
796	
797	    /**
798	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
799	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
800	     * lower-cased.
801	     *
802	     * @param value the raw value to normalize (may be {@code null})
803	     * @return the normalized value, or an empty string when {@code value} is {@code null}
804	     */
805	    private String normalizeForComparison(String value) {
806	        if (value == null) {
807	            return "";
808	        }
809	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
810	    }
811	}
